            const d=rt.renderTargetLayers?.[idx]||rt.targetVisuals?.[idx]||s;if(!s||!d)return NaN;
            if(!(s.spiralEnabled===true||d.spiralEnabled===true||isSpiralLayer?.(layer)))return NaN;
