            setRange('paramGlow', glow, 0, 40, '0.01'); setText('valGlow', glow, 'px');

            const glowIntensity = Math.max(0, Math.min(200, Number.isFinite(Number(activeLayer?.glowIntensity)) ? Number(activeLayer.glowIntensity) : 40));
            setRange('paramGlowIntensity', glowIntensity, 0, 200, '1');
