        function playlistPaletteTotalCount(record){return expandPlaylistPalette(record).length;}
        function resetPlaylistPalette(key){
            const palettes=ensurePlaylistColorPalettes(),old=palettes[key];if(!old)return;
            const keepActive=old.active!==false;
            if(FACTORY_PLAYLIST_PALETTE_RECORDS[key])palettes[key]=factoryPlaylistPaletteRecord(key);
            else palettes[key]={id:key,name:old.name||'Новая палитра',keyColors:['#22d3ee','#f472b6'],multiplier:1,saturation:100,brightness:50,contrast:50,active:true,factoryKey:null,exactColors:null};
            palettes[key].active=keepActive;playlistPaletteExpandedKey=key;playlistPaletteSelectedIndex.set(key,0);schedulePlaylistPaletteRuntimeRefresh(key);showShortcutToast('Палитра сброшена');
        }
        function insertPlaylistPaletteKeyColor(key,side){
            const r=getPlaylistPaletteRecord(key);if(!r)return;
            const idx=getSelectedPlaylistPaletteIndex(key,r);const colors=r.keyColors;
            const insertAt=side==='left'?idx:idx+1;
            const neighbor=side==='left'?colors[idx-1]:colors[idx+1];
            const selected=colors[idx]||'#ffffff';
            const nextColor=neighbor?paletteLerpHex(selected,neighbor,.5):selected;
            markPlaylistPaletteEdited(r);colors.splice(insertAt,0,nextColor);setSelectedPlaylistPaletteIndex(key,insertAt,r);/* getPlaylistPaletteColors() sees this key immediately, so both morph engines can pick it from the very next random choice. */renderPlaylistPaletteStudio();schedulePlaylistPaletteRuntimeRefresh(key);
        }
        function removeSelectedPlaylistPaletteKeyColor(key){
            const r=getPlaylistPaletteRecord(key);if(!r)return;
            if(r.keyColors.length<=2){showShortcutToast('Оставьте минимум два ключевых цвета');return;}
            const idx=getSelectedPlaylistPaletteIndex(key,r);markPlaylistPaletteEdited(r);r.keyColors.splice(idx,1);setSelectedPlaylistPaletteIndex(key,Math.min(idx,r.keyColors.length-1),r);renderPlaylistPaletteStudio();schedulePlaylistPaletteRuntimeRefresh(key);
        }
        function paletteVisibleLuminance(raw,record){
            const h=applyPlaylistHueOffsetHex(paletteAdjustHex(raw,record));const vals=[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));
            return .2126*vals[0]+.7152*vals[1]+.0722*vals[2];
        }
        function sortPlaylistPaletteByBrightness(key){
            const r=getPlaylistPaletteRecord(key);if(!r)return;
            const selected=getSelectedPlaylistPaletteIndex(key,r);
            const decorated=r.keyColors.map((color,index)=>({color,index,selected:index===selected,lum:paletteVisibleLuminance(color,r)}));
            decorated.sort((a,b)=>b.lum-a.lum||a.index-b.index);markPlaylistPaletteEdited(r);r.keyColors=decorated.map(x=>x.color);playlistPaletteSelectedIndex.set(key,Math.max(0,decorated.findIndex(x=>x.selected)));renderPlaylistPaletteStudio();schedulePlaylistPaletteRuntimeRefresh(key);
        }
        function beginPaletteLeftDrag(e,key,record,strip,seg){
            if(e.button!==0)return;
            e.preventDefault();e.stopPropagation();
            const startX=e.clientX,startY=e.clientY;let dragging=false;
            setSelectedPlaylistPaletteIndex(key,[...strip.children].indexOf(seg),record);
            strip.querySelectorAll('.palette-key-segment').forEach(el=>el.classList.toggle('selected',el===seg));
            const move=ev=>{
                if((ev.buttons&1)!==1)return;
                const dx=Math.abs(ev.clientX-startX),dy=Math.abs(ev.clientY-startY);
                if(!dragging&&Math.max(dx,dy)<4)return;
                dragging=true;seg.classList.add('left-dragging');ev.preventDefault();ev.stopPropagation();
                const rect=strip.getBoundingClientRect(),count=strip.children.length;if(!count||rect.width<=0)return;
                let target=Math.floor(((ev.clientX-rect.left)/rect.width)*count);target=Math.max(0,Math.min(count-1,target));
                const children=[...strip.children],current=children.indexOf(seg);if(current<0||target===current)return;
                if(target>current)strip.insertBefore(seg,strip.children[target]?.nextSibling||null);else strip.insertBefore(seg,strip.children[target]||null);
            };
            const finish=ev=>{
                document.removeEventListener('pointermove',move,true);document.removeEventListener('pointerup',finish,true);document.removeEventListener('pointercancel',finish,true);seg.classList.remove('left-dragging');
                const nodes=[...strip.children],newIndex=Math.max(0,nodes.indexOf(seg));playlistPaletteSelectedIndex.set(key,newIndex);
                if(dragging){
                    markPlaylistPaletteEdited(record);record.keyColors=nodes.map(n=>n.dataset.rawColor||'#ffffff');
                    renderPlaylistPaletteStudio();schedulePlaylistPaletteRuntimeRefresh(key);
                }
            };

            document.addEventListener('pointermove',move,true);document.addEventListener('pointerup',finish,true);document.addEventListener('pointercancel',finish,true);
        }

