                    const resetBtn=document.createElement('button');resetBtn.type='button';resetBtn.className='palette-reset-btn';resetBtn.textContent='↻';resetBtn.title='Сбросить палитру к стандартным значениям';resetBtn.setAttribute('aria-label','Сбросить палитру');resetBtn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();resetPlaylistPalette(key);});
                    nameRow.append(nameInput,resetBtn);editor.appendChild(nameRow);
