                    const addLeft=document.createElement('button');addLeft.type='button';addLeft.textContent='＋ слева';addLeft.title='Добавить цвет слева от выбранного';addLeft.addEventListener('click',()=>insertPlaylistPaletteKeyColor(key,'left'));
                    const addRight=document.createElement('button');addRight.type='button';addRight.textContent='＋ справа';addRight.title='Добавить цвет справа от выбранного';addRight.addEventListener('click',()=>insertPlaylistPaletteKeyColor(key,'right'));
                    const sort=document.createElement('button');sort.type='button';sort.textContent='☀ яркость';sort.title='Выстроить ключевые цвета от самого яркого к самому тёмному';sort.addEventListener('click',()=>sortPlaylistPaletteByBrightness(key));
                    actions.append(rem,addLeft,addRight,sort);editor.appendChild(actions);
                    if(!record.factoryKey){const del=document.createElement('button');del.type='button';del.className='palette-delete-palette-btn';del.textContent='Удалить палитру';del.addEventListener('click',()=>{if(!confirm(`Удалить палитру «${record.name}»?`))return;delete palettes[key];playlistPaletteSelectedIndex.delete(key);playlistPaletteExpandedKey='';ensureSelectedPaletteActive();renderPlaylistPaletteButtons();renderPlaylistPaletteStudio();renderPaletteQuickMenu();});editor.appendChild(del);}
                    const makeControl=(label,min,max,value,onInput,step=1)=>{const row=document.createElement('div');row.className='palette-editor-control';const l=document.createElement('span');l.textContent=label;const range=document.createElement('input');range.type='range';range.min=min;range.max=max;range.step=step;range.value=value;const num=document.createElement('input');num.type='number';num.min=min;num.max=max;num.step=step;num.value=value;const update=v=>{range.value=v;num.value=v;onInput(Number(v));};range.addEventListener('input',()=>update(range.value));num.addEventListener('input',()=>update(num.value));row.append(l,range,num);return row;};
