                    for (let i = 0; i < cumulative.length - 1; i++) {
                        if (d <= cumulative[i+1] + 1e-12) { seg = i; break; }
                    }
                    const span = Math.max(1e-9, cumulative[seg+1] - cumulative[seg]);
