                const transmittedT=(typeof morphInterpolationTForCurrentMode==='function')?morphInterpolationTForCurrentMode(Number.isFinite(geometryT)?geometryT:easedT):easedT;
                const out={mode:state?.morph?.mode||'',speedType:state?.morph?.speedType||'linear',linearT,easedT,geometryT:Number.isFinite(geometryT)?geometryT:null,transmittedT,overshootPreserved:['topology','calm'].includes(state?.morph?.mode||'')};
