                    if(fromId && Object.prototype.hasOwnProperty.call(enabled,fromId))nextEnabled[toId]=enabled[fromId];
                    else if(Object.prototype.hasOwnProperty.call(enabled,toId))nextEnabled[toId]=enabled[toId];
