        function bindRandomPanelAndMorphRebaseHooks(bindingContext) {
            const getActiveLayer = bindingContext.getActiveLayer;
            document.getElementById('btnRandomSettings').addEventListener('click', (e) => {
                e.stopPropagation();
                const panel = document.getElementById('randomSettingsPanel');
                const opening = panel.classList.contains('hidden');
                panel.classList.toggle('hidden', !opening);
                document.getElementById('morphSettingsPanel')?.classList.add('hidden');
                if (opening) positionFloatingPanelNearTrigger?.(panel, e.currentTarget);
            });
            document.getElementById('randomSettingsPanel').addEventListener('click', (e) => e.stopPropagation());
            document.addEventListener('click', () => document.getElementById('randomSettingsPanel')?.classList.add('hidden'));

            const randomOptionMap = {
                randomByShape: 'byShape',
                randomOnlyLine: 'onlyLine',
                randomByVertices: 'byVertices',
                randomBySteps: 'bySteps',
                randomByRounding: 'byRounding',
                randomBySize: 'bySize',
                randomByColor: 'byColor',
                randomBySpiralLayers: 'bySpiralLayers'
            };
            Object.entries(randomOptionMap).forEach(([id, key]) => {
                const el = document.getElementById(id);
                if (!el) return;
                el.addEventListener('change', (e) => {
                    state.randomOptions[key] = e.target.checked;
                    if (key === 'onlyLine' && e.target.checked) {
                        state.randomOptions.byShape = false;
                        const shapeEl = document.getElementById('randomByShape');
                        if (shapeEl) shapeEl.checked = false;
                    } else if (key === 'byShape' && e.target.checked) {
                        state.randomOptions.onlyLine = false;
                        const lineEl = document.getElementById('randomOnlyLine');
                        if (lineEl) lineEl.checked = false;
                    }
                    if(key==='byColor')syncPlaylistPaletteSelectionUI();
                });
            });

            const syncRandomSpiralLayerRange = (changedId = '') => {
                let lo = Math.max(0, Math.min(8, Math.round(Number(document.getElementById('randomSpiralLayersMin')?.value) || 0)));
                let hi = Math.max(0, Math.min(8, Math.round(Number(document.getElementById('randomSpiralLayersMax')?.value) || 0)));
                if (lo > hi) { if (changedId === 'randomSpiralLayersMin') hi = lo; else lo = hi; }
                state.randomOptions.spiralLayersMin = lo;
                state.randomOptions.spiralLayersMax = hi;
                const a = document.getElementById('randomSpiralLayersMin'), b = document.getElementById('randomSpiralLayersMax');
                if (a) a.value = lo; if (b) b.value = hi;
            };
            document.getElementById('randomSpiralLayersMin')?.addEventListener('change', () => syncRandomSpiralLayerRange('randomSpiralLayersMin'));
            document.getElementById('randomSpiralLayersMax')?.addEventListener('change', () => syncRandomSpiralLayerRange('randomSpiralLayersMax'));

            const sidebar = document.getElementById('settingsSidebar') || document.querySelector('aside');
            const beginSidebarMorphRebase=(e)=>{
                if(!runtimeState.morph.active||e.target.closest?.('#profileCanvas'))return;
                const source=state.layers.find(l=>l.id===state.activeLayerId);if(!source)return;
                if(!morphSidebarRebaseRuntime.queued){
                    morphSidebarRebaseRuntime.active=true;
                    morphSidebarRebaseRuntime.queued=true;
                    morphSidebarRebaseRuntime.pending=false;
                    morphSidebarRebaseRuntime.before=masterLayerSnapshot(source);
                    morphSidebarRebaseRuntime.sourceId=source.id||null;
                    morphSidebarRebaseRuntime.eventType=String(e.type||'');
                    morphSidebarRebaseRuntime.targetId=String(e.target?.id||e.target?.dataset?.contourMode||'');
                    queueMicrotask(()=>queueMicrotask(()=>{
                        const tx=morphSidebarRebaseRuntime;
                        const current=state.layers.find(l=>l.id===tx.sourceId)||state.layers.find(l=>l.id===state.activeLayerId)||null;
                        const after=current?masterLayerSnapshot(current):{};
                        const changed=current?collectMasterChangedPaths(tx.before||{},after):[];

                        if(current&&changed.some(path=>path==='profileMode'||path==='profileNodes')&&contourModeIsSpiral(getContourMode(current))){
                            for(const path of ['spiralEnabled','spiralClosed','spiralOrder','closedLoop'])if(!changed.includes(path))changed.push(path);
                        }
                        const shouldRebase=tx.pending||changed.length>0;
                        tx.active=false;tx.queued=false;tx.pending=false;tx.before=null;tx.sourceId=null;
                        if(shouldRebase&&runtimeState.morph.active){
                            activeRebaseMorphing({preservePaths:changed,fromSidebarTransaction:true});
                            requestMainCanvasRender();
                        }
                    }));
                }
            };
            ['input','change','click'].forEach(type=>sidebar?.addEventListener(type,beginSidebarMorphRebase,true));
        }

        function bindInputEvents() {
            const bindingContext = Object.freeze({
                getActiveLayer: () => state.layers.find(l => l.id === state.activeLayerId)
            });
            bindMasterAndDisplayControls(bindingContext);
            bindLayerGeometryAndStyleControls(bindingContext);
            bindProfileEditorControls(bindingContext);
            bindLayerCollectionControls(bindingContext);
            bindPresetRandomMorphControls(bindingContext);
            bindRandomPanelAndMorphRebaseHooks(bindingContext);
        }

        function bindViewportEvents() {

            const viewportSurface=document.getElementById('mainContainer')||mainCanvas;
            const viewportGestureAllowed=(target)=>!target?.closest?.('button,input,select,textarea,a,label,[role=\"button\"],#floatingViewportControls,#fpsCounter,[contenteditable=\"true\"],.no-viewport-gesture');
            document.getElementById('btnZoomIn').addEventListener('click', () => {
                state.zoom = Math.min(state.zoom * 1.2, 5.0);
                document.getElementById('zoomDisplay').textContent = Math.round(state.zoom * 100) + '%';
                renderMainCanvas();
            });

            document.getElementById('btnZoomOut').addEventListener('click', () => {
                state.zoom = Math.max(state.zoom / 1.2, 0.2);
                document.getElementById('zoomDisplay').textContent = Math.round(state.zoom * 100) + '%';
                renderMainCanvas();
            });

            document.getElementById('btnResetView').addEventListener('click', () => {
                state.zoom = window.matchMedia('(max-width: 760px), (max-height: 480px) and (hover: none) and (pointer: coarse)').matches ? 0.9 : 1.0;
                state.panX = 0;
                state.panY = 0;
                document.getElementById('zoomDisplay').textContent = Math.round(state.zoom * 100) + '%';
                renderMainCanvas();
            });

            document.getElementById('zoomDisplay')?.addEventListener('dblclick',(e)=>{
                e.preventDefault();
                e.stopPropagation();
                state.zoom=1.0;
                document.getElementById('zoomDisplay').textContent='100%';
                renderMainCanvas();
            });

            viewportSurface.addEventListener('mousedown', (e) => {
                if (!viewportGestureAllowed(e.target)) return;
                if (e.button === 0 || e.button === 1) {
                    state.isPanning = true;
                    state.lastMousePos = { x: e.clientX, y: e.clientY };
                    viewportSurface.style.cursor = 'grabbing';
                }
            });

            window.addEventListener('mousemove', (e) => {
                if (state.isPanning) {
                    const dx = e.clientX - state.lastMousePos.x;
                    const dy = e.clientY - state.lastMousePos.y;
                    state.panX += dx;
                    state.panY += dy;
                    state.lastMousePos = { x: e.clientX, y: e.clientY };
                    renderMainCanvas();
                }
            });

            window.addEventListener('mouseup', () => {
                if (state.isPanning) {
                    state.isPanning = false;
                    viewportSurface.style.cursor = 'default';
                }
            });

            viewportSurface.addEventListener('wheel', (e) => {
                if (!viewportGestureAllowed(e.target)) return;
                e.preventDefault();
                const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
                state.zoom = Math.max(0.2, Math.min(5.0, state.zoom * zoomFactor));
                document.getElementById('zoomDisplay').textContent = Math.round(state.zoom * 100) + '%';
                renderMainCanvas();
            }, { passive: false });

            let canvasTouchMode = null;
            let canvasLastTouch = null;
            let pinchStartDistance = 0;
            let pinchStartZoom = 1;
            let pinchLastMid = null;

            const touchDistance = (a, b) => Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
            const touchMidpoint = (a, b) => ({
                x: (a.clientX + b.clientX) / 2,
                y: (a.clientY + b.clientY) / 2
            });

            viewportSurface.addEventListener('touchstart', (e) => {
                if (!viewportGestureAllowed(e.target)) return;
                e.preventDefault();
                if (e.touches.length === 1) {
                    canvasTouchMode = 'pan';
                    canvasLastTouch = { x: e.touches[0].clientX, y: e.touches[0].clientY };
                    state.isPanning = false;
                } else if (e.touches.length >= 2) {
                    canvasTouchMode = 'pinch';
                    state.isPanning = false;
                    pinchStartDistance = Math.max(1, touchDistance(e.touches[0], e.touches[1]));
                    pinchStartZoom = state.zoom;
                    pinchLastMid = touchMidpoint(e.touches[0], e.touches[1]);
                }
            }, { passive: false });

            viewportSurface.addEventListener('touchmove', (e) => {
                if (!canvasTouchMode) return;
                e.preventDefault();
                if (e.touches.length === 1 && canvasTouchMode === 'pan' && canvasLastTouch) {
                    const t = e.touches[0];
                    state.panX += t.clientX - canvasLastTouch.x;
                    state.panY += t.clientY - canvasLastTouch.y;
                    canvasLastTouch = { x: t.clientX, y: t.clientY };
                    renderMainCanvas();
                    return;
                }

                if (e.touches.length >= 2) {
                    if (canvasTouchMode !== 'pinch') {
                        canvasTouchMode = 'pinch';
                        pinchStartDistance = Math.max(1, touchDistance(e.touches[0], e.touches[1]));
                        pinchStartZoom = state.zoom;
                        pinchLastMid = touchMidpoint(e.touches[0], e.touches[1]);
                    }

                    const distance = Math.max(1, touchDistance(e.touches[0], e.touches[1]));
                    const mid = touchMidpoint(e.touches[0], e.touches[1]);
                    state.zoom = Math.max(0.2, Math.min(5.0, pinchStartZoom * (distance / pinchStartDistance)));
                    if (pinchLastMid) {
                        state.panX += mid.x - pinchLastMid.x;
                        state.panY += mid.y - pinchLastMid.y;
                    }
                    pinchLastMid = mid;
                    document.getElementById('zoomDisplay').textContent = Math.round(state.zoom * 100) + '%';
                    renderMainCanvas();
                }
            }, { passive: false });

            viewportSurface.addEventListener('touchend', (e) => {
                // Only a gesture that began on the canvas may cancel the native touch.
                // Touches on the floating bottom toolbar bubble through mainContainer;
                // cancelling them here suppresses their synthesized click on phones.
                if (!canvasTouchMode) return;
                e.preventDefault();
                if (e.touches.length === 1) {
                    canvasTouchMode = 'pan';
                    canvasLastTouch = { x: e.touches[0].clientX, y: e.touches[0].clientY };
                } else {
                    canvasTouchMode = null;
                    canvasLastTouch = null;
                    pinchLastMid = null;
                }
            }, { passive: false });

            viewportSurface.addEventListener('touchcancel', () => {
                canvasTouchMode = null;
                canvasLastTouch = null;
                pinchLastMid = null;
            }, { passive: false });
        }

