        function uniquePlaylistProjectName(name, ignoreId=null, entries=state.playlistProjects||[]) {
            const base=String(name||'Проект один').trim()||'Проект один';
            const used=new Set((entries||[]).filter(e=>!ignoreId||e.id!==ignoreId).map(e=>String(e?.name||'').trim().toLocaleLowerCase('ru-RU')));
            if(!used.has(base.toLocaleLowerCase('ru-RU')))return base;
            let n=2,candidate=`${base} (${n})`;
            while(used.has(candidate.toLocaleLowerCase('ru-RU'))){n++;candidate=`${base} (${n})`;}
            return candidate;
        }
