            pm.advancedLinear = typeof src.advancedLinear === 'boolean' ? src.advancedLinear : (pm.advancedLinear === true);

            const legacyTransition = Number.isFinite(Number(src.transitionSec))
                ? Number(src.transitionSec)
                : (Number.isFinite(Number(src.fadeSec)) && Number(src.fadeSec) > 0 ? Number(src.fadeSec) : NaN);
            pm.transitionSec = Math.max(0, Number.isFinite(legacyTransition) ? legacyTransition : (Number(pm.transitionSec) || 4));
            const requestedImageTransitionType = typeof src.imageTransitionType === 'string' ? src.imageTransitionType : pm.imageTransitionType;
            pm.imageTransitionType = ['instant','fade','slide','center','sector'].includes(requestedImageTransitionType) ? requestedImageTransitionType : 'fade';
            pm.imageCenterSoftness = Math.max(0,Math.min(100,Number.isFinite(Number(src.imageCenterSoftness)) ? Number(src.imageCenterSoftness) : (Number(pm.imageCenterSoftness ?? 24))));
            pm.imageSectorSoftness = Math.max(0,Math.min(100,Number.isFinite(Number(src.imageSectorSoftness)) ? Number(src.imageSectorSoftness) : (Number(pm.imageSectorSoftness ?? 18))));

            pmRt.fadeProgress = Math.max(0, Math.min(1, Number(pmRt.fadeProgress) || 0));
            pmRt.progress = Math.max(0, Math.min(1, Number(pmRt.progress) || 0));
            pmRt.renderProgress = Math.max(0, Math.min(1, Number(pmRt.renderProgress) || 0));
            pmRt.parameterProgress = Math.max(0, Math.min(1, Number(pmRt.parameterProgress) || 0));
            pmRt.transitionProgress = Math.max(0, Math.min(1, Number(pmRt.transitionProgress) || 0));
