        function positionCompactMenu(menu,x,y){if(!menu)return;menu.classList.remove('hidden');menu.style.visibility='hidden';const vw=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),vh=Math.max(document.documentElement.clientHeight||0,window.innerHeight||0),m=8;const r=menu.getBoundingClientRect();menu.style.left=`${Math.max(m,Math.min(vw-r.width-m,x))}px`;menu.style.top=`${Math.max(m,Math.min(vh-r.height-m,y))}px`;menu.style.visibility='';}
