        V286_FLOATING_PANELS.forEach(spec=>{const panel=document.getElementById(spec.panel);if(panel)new MutationObserver(()=>{if(!panel.classList.contains('hidden'))requestAnimationFrame(()=>v286FitFloatingPanel(panel));}).observe(panel,{attributes:true,attributeFilter:['class']});});

