                const values=document.createElement('span'); values.className='audio-custom-band-values';
                const loNum=document.createElement('input');loNum.type='number';loNum.min='20';loNum.max='20000';loNum.step='1';loNum.inputMode='numeric';loNum.value=String(Math.round(loHz));loNum.setAttribute('aria-label',`${labels[key]}: нижняя частота`);
