            document.querySelectorAll('[data-audio-meter]').forEach(m=>m.style.width='0%');document.querySelectorAll('[data-audio-value]').forEach(v=>v.textContent='0%');
            paintAudioInputMonitor();
            paintAudioRoutingMeters();
