            const attach=el=>{if(el.dataset.multEditable==='1')return;const row=el.closest('.control-row,.tunnel-setting,.morph-setting-row,.audio-master-effects-amplitude,.lamp-slider-mult')||el.parentElement;if(!row)return;const mult=[...row.querySelectorAll('input[type="number"]')].find(isMultiplierNumberInput);const range=row.querySelector('input[type="range"]');if(!mult||!range)return;el.dataset.multEditable='1';el.contentEditable='true';el.classList.add('editable-mult-summary');el.title='Можно ввести вручную: значение × множитель';el.addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();el.blur();}});el.addEventListener('blur',()=>{const nums=(el.textContent.match(/-?\d+(?:[.,]\d+)?/g)||[]).map(x=>Number(x.replace(',','.')));if(nums.length>=2){range.value=String(nums[0]);mult.value=String(Math.max(0,nums[1]));range.dispatchEvent(new Event('input',{bubbles:true}));mult.dispatchEvent(new Event('input',{bubbles:true}));mult.dispatchEvent(new Event('change',{bubbles:true}));}});};
            document.querySelectorAll('.text-mono,.audio-route-gain-value').forEach(el=>{if(el.textContent.includes('×'))attach(el);});
            const observer=new MutationObserver(()=>document.querySelectorAll('.text-mono,.audio-route-gain-value').forEach(el=>{if(el.textContent.includes('×'))attach(el);}));observer.observe(document.body,{childList:true,subtree:true});
